	add           ( listener, target )
	addToTop      ( listener, target )
	once          ( listener, target )
	remove        ( listener )
	removeAll     ()
	getLength     () // returns the number of listeners
	broadcast     ()
	stopBroadcast ()
	eachReturn    property function
}
